import json
a=json.load(open('outputs/analytics.json'))
def walk(o,p='\$',d=0):
  if isinstance(o,dict):
    for k,v in o.items():
      if k in ('top20','top_20','rows','top') : print(p+'.'+k, '[list len %d]'%len(v) if isinstance(v,list) else type(v).__name__); continue
      walk(v,p+'.'+str(k),d+1)
  elif isinstance(o,list):
    print(p,'[list len %d]'%len(o), (json.dumps(o[0])[:200] if o and not isinstance(o[0],dict) else (list(o[0].keys())[:12] if o else '')))
  else:
    s=json.dumps(o); print(p,'=',s[:160])
walk(a)
